on conflict (id) do update set name = excluded.name, email = excluded.email, pin = excluded.pin, active = excluded.active, notes = excluded.notes;

on conflict (id) do update set name = excluded.name, cif = excluded.cif, email = excluded.email, phone = excluded.phone, contact_person = excluded.contact_person, delivery_address = excluded.delivery_address, pin = excluded.pin, active = excluded.active, notes = excluded.notes;

on conflict (id) do update set name = excluded.name, key = excluded.key, icon = excluded.icon, sort_order = excluded.sort_order, active = excluded.active;

on conflict (id) do update set sku = excluded.sku, name = excluded.name, category_id = excluded.category_id, subcategory_id = excluded.subcategory_id, category_name = excluded.category_name, subcategory_name = excluded.subcategory_name, price = excluded.price, stock = excluded.stock, description = excluded.description, brand = excluded.brand, unit_measure = excluded.unit_measure, units_per_box = excluded.units_per_box, image_url = excluded.image_url, weight_kg = excluded.weight_kg, iva = excluded.iva, active = excluded.active;
